-- Doctor master aligned with HIS doctor list + permission flags.
-- Prefer: npm run db:push when the DB is reachable.
-- If the old doctor table exists, drop it first (data loss).

DROP TABLE IF EXISTS "doctor";

CREATE TABLE "doctor" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"hisid" integer,
	"facility_name" text,
	"drnno" text,
	"doctor_name" text,
	"specialization" text,
	"active" boolean DEFAULT true
);

ALTER TABLE "access_role" ADD COLUMN IF NOT EXISTS "nav_doctors" boolean DEFAULT true NOT NULL;
ALTER TABLE "access_role" ADD COLUMN IF NOT EXISTS "doctor_read_all" boolean DEFAULT false NOT NULL;
ALTER TABLE "access_role" ADD COLUMN IF NOT EXISTS "doctor_write" boolean DEFAULT false NOT NULL;
ALTER TABLE "access_role" ADD COLUMN IF NOT EXISTS "doctor_delete" boolean DEFAULT false NOT NULL;

UPDATE access_role
SET doctor_read_all = true, doctor_write = true, doctor_delete = true
WHERE slug = 'manager';

UPDATE access_role
SET doctor_write = true, doctor_delete = true
WHERE slug = 'hr';

UPDATE access_role
SET doctor_read_all = true
WHERE slug = 'viewer';
